import { renderSlot } from 'vue'
import { useLocale, useNamespace } from '@element-plus/hooks'

import type { CSSProperties, FunctionalComponent } from 'vue'

type EmptyRendererProps = {
  class?: JSX.IntrinsicAttributes['class']
  style?: CSSProperties
}

const Empty: FunctionalComponent<EmptyRendererProps> = (props, { slots }) => {
  const { t } = useLocale()
  const ns = useNamespace('table-v2')
  const defaultSlot = renderSlot(slots, 'default', {}, () => [
    <span class={ns.e('empty-text')}>({t('el.table.emptyText')})</span>,
  ])
  return (
    <div class={props.class} style={props.style}>
      {defaultSlot}
    </div>
  )
}

Empty.displayName = 'ElTableV2Empty'

export default Empty
